multi			    ((2.0e-19)*Processor_Speed_MHz*Processor_Speed_MHz*1.0e12)+ ((-6.0e-11)*Processor_Speed_MHz*1.0e6)+0.017 ;
act			    multi				 ;
stdy			    0.1*act				 ;
wat			    0.95*act				 ;
idl			    0.25*act				 ;
slp			    0.02*act				 ;

