coreArr			= createSequence(1,1,5)
LABEL:BEGIN
destination		= port_token.A_Destination
numindex		= destination.lastIndexOf("_")
if(numindex		>= 0)	{
	core_		= destination.substring(numindex+1,destination.length())
	core		= cast(1,core_)
}
else					{
	core		= 1
}
index			= coreArr.search(core)
latency			= TNow - port_token.Time_Stamp
plotDS			= {legend = "Core_"+core,color=index,latency=latency}
SEND(output,plotDS)

coreArr			= createSequence(1,1,5)
LABEL:BEGIN
destination		= port_token.A_Destination
numindex		= destination.lastIndexOf("_")
if(numindex		>= 0)	{
	core_		= destination.substring(numindex+1,destination.length())
	core		= cast(1,core_)
}
else					{
	core		= 1
}
index			= coreArr.search(core)
plotDS			= {legend = "Core_"+core,color=index,mips=port_token.MIPS_IN_PROCESSOR}
SEND(output,plotDS)

